{
  "packs": [
    {
      "id": "spec-driven-product",
      "version": "60822.1"
    },
    {
      "id": "executable-requirements",
      "version": "60822.1",
      "answers": {
        "ui_testing": "Flutter widget-test golden rendering — screen/saga/behavior/logic kinds under dev/requirements/, driven via `flutter test` (test/*_requirements_test.dart) or python3 run_requirements.py. screen and saga leaves assert a pixel-exact (or byte-identical APNG) golden the owner checks by sight; behavior/logic leaves assert coded expectations against the shipped app shell.",
        "requirements_source": "authored fresh at dev/requirements/requirements.md, porting the executable-requirements discipline from the GoogleCalendarEventCreator project to Flutter (dev/requirements/README.md)."
      }
    },
    {
      "id": "flutter",
      "version": "60822.1"
    },
    {
      "id": "android",
      "version": "60822.1"
    },
    {
      "id": "ios",
      "version": "60822.1"
    },
    {
      "id": "firebase",
      "version": "60822.1"
    },
    {
      "id": "node",
      "version": "60823.1",
      "config": {
        "dirs": [
          "firebase/functions"
        ]
      }
    },
    {
      "id": "basics",
      "version": "60823.1"
    },
    {
      "id": "barriers",
      "version": "60823.1",
      "via": [
        "basics"
      ]
    },
    {
      "id": "tidy-repo",
      "version": "60823.1"
    },
    {
      "id": "claudinite-growth",
      "version": "60823.2"
    },
    "local/shouts-and-whispers",
    {
      "id": "claude-code-web-users-support",
      "version": "60823.1",
      "config": {
        "repo": "missingbulb/Shepherd"
      },
      "answers": {
        "store": "missingbulb/Shepherd"
      }
    },
    {
      "id": "claudinite-lifecycle",
      "version": "60823.1"
    }
  ],
  "accept": [
    {
      "rule": "pack-declaration",
      "path": ".claudinite-settings.json",
      "reason": "node genuinely applies but its package.json lives at firebase/functions/package.json — two directories down, past the node pack's intentional near-root fingerprint cap (root or one dir down) that keeps nested fixtures from tripping detection. So the declaration is deliberately ahead of the fingerprint here. Every other declared pack fingerprint-matches without acceptance: flutter (app/pubspec.yaml), firebase (firebase/firebase.json, one dir down — now detected since Claudinite PR #190), android (app/android/.../AndroidManifest.xml), ios (app/ios/Runner/Info.plist), executable-requirements (dev/requirements/requirements.md)."
    }
  ],
  "taskScheduler": {
    "agenticTaskInvocationEndpoints": {
      "default": {
        "url": "[REDACTED:env:ANTHROPIC_BASE_URL]/v1/claude_code/routines/trig_01VoSm2pim6PjfD6aBuh3Ahe/fire",
        "tokenSecret": "CCR_ROUTINE_TOKEN"
      }
    },
    "dailyHour": 4,
    "weeklyDay": "Sun",
    "monthlyDay": 1
  },
  "engineVersion": "60823.1"
}

